48	public class GlobalExceptionHandler {
49	
50	    @ExceptionHandler(MethodArgumentNotValidException.class)
51	    public ProblemDetail handleMethodArgumentNotValid(MethodArgumentNotValidException ex) {
52	        List<ValidationError> errors = ex.getBindingResult().getAllErrors().stream()
53	                .map(GlobalExceptionHandler::toValidationError)
54	                .sorted(Comparator.comparing(ValidationError::field, Comparator.nullsFirst(Comparator.naturalOrder()))
55	                        .thenComparing(ValidationError::message))
56	                .toList();
57	        return validationProblem(errors);
58	    }
59	
60	    @ExceptionHandler(HttpMessageNotReadableException.class)
61	    public ProblemDetail handleNotReadable(HttpMessageNotReadableException ex) {
62	        return validationProblem(List.of(toValidationError(ex.getCause())));
63	    }
64	
65	    @ExceptionHandler(NotFoundException.class)
66	    public ProblemDetail handleNotFound(NotFoundException ex) {
67	        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
68	    }
69	
70	    @ExceptionHandler(ConflictException.class)
71	    public ProblemDetail handleConflict(ConflictException ex) {
72	        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, ex.getMessage());
73	    }
74	
75	    // Safety net for races only: uniqueness rules are checked by the services.
76	    @ExceptionHandler(DataIntegrityViolationException.class)
77	    public ProblemDetail handleDataIntegrityViolation(DataIntegrityViolationException ex) {
78	        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, "Request conflicts with existing data");
79	    }
80	
81	    private static ProblemDetail validationProblem(List<ValidationError> errors) {
82	        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "Validation failed");
83	        problem.setProperty("errors", errors);
84	        return problem;
85	    }
86	
87	    private static ValidationError toValidationError(ObjectError error) {
88	        String field = error instanceof FieldError fieldError ? fieldError.getField() : null;
89	        return new ValidationError(field, error.getDefaultMessage());
90	    }
91	
92	    private static ValidationError toValidationError(Throwable cause) {
93	        if (!(cause instanceof JsonMappingException mapping) || mapping.getPath().isEmpty()) {
94	            return new ValidationError(null, "request body must be valid JSON");
95	        }
96	        String field = mapping.getPath().stream()
97	                .map(reference -> reference.getFieldName() != null
98	                        ? "." + reference.getFieldName()
99	                        : "[" + reference.getIndex() + "]")
100	                .collect(Collectors.joining())
101	                .replaceFirst("^\\.", "");
102	        if (cause instanceof InvalidFormatException invalidFormat && invalidFormat.getTargetType().isEnum()) {
103	            String allowed = Arrays.stream(invalidFormat.getTargetType().getEnumConstants())
104	                    .map(String::valueOf)
105	                    .collect(Collectors.joining(", "));
106	            return new ValidationError(field, "must be one of: " + allowed);
107	        }
108	        return new ValidationError(field, "has an invalid value");
109	    }
110	}
