452	@Service
453	@Transactional(readOnly = true)
454	public class VehicleService {
455	
456	    private final VehicleRepository vehicleRepository;
457	
458	    public VehicleService(VehicleRepository vehicleRepository) {
459	        this.vehicleRepository = vehicleRepository;
460	    }
461	
462	    public List<VehicleResponse> findAll() {
463	        return vehicleRepository.findAll(Sort.by("id")).stream()
464	                .map(VehicleMapper::toResponse)
465	                .toList();
466	    }
467	
468	    public VehicleResponse findById(Long id) {
469	        return VehicleMapper.toResponse(getVehicle(id));
470	    }
471	
472	    @Transactional
473	    public VehicleResponse create(VehicleRequest request) {
474	        if (vehicleRepository.existsByVin(request.vin())) {
475	            throw vinAlreadyExists(request.vin());
476	        }
477	        Vehicle vehicle = vehicleRepository.save(VehicleMapper.toEntity(request));
478	        return VehicleMapper.toResponse(vehicle);
479	    }
480	
481	    @Transactional
482	    public VehicleResponse update(Long id, VehicleRequest request) {
483	        Vehicle vehicle = getVehicle(id);
484	        if (vehicleRepository.existsByVinAndIdNot(request.vin(), id)) {
485	            throw vinAlreadyExists(request.vin());
486	        }
487	        VehicleMapper.updateEntity(vehicle, request);
488	        return VehicleMapper.toResponse(vehicleRepository.save(vehicle));
489	    }
490	
491	    @Transactional
492	    public void delete(Long id) {
493	        vehicleRepository.delete(getVehicle(id));
494	    }
495	
496	    private Vehicle getVehicle(Long id) {
497	        return vehicleRepository.findById(id)
498	                .orElseThrow(() -> new NotFoundException("Vehicle with id " + id + " not found"));
499	    }
500	
501	    private static ConflictException vinAlreadyExists(String vin) {
502	        return new ConflictException("Vehicle with VIN " + vin + " already exists");
503	    }
