## `Widget.java`

```java
package com.example.dealership.widget;

import java.time.LocalDate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "widget")
public class Widget {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, length = 20)
    private String code;

    @Column(nullable = false, length = 50)
    private String name;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private WidgetKind kind;

    private LocalDate validFrom;

    @Column(nullable = false)
    private boolean active;

    protected Widget() {
    }

    public Widget(String code, String name, WidgetKind kind, LocalDate validFrom, boolean active) {
        this.code = code;
        this.name = name;
        this.kind = kind;
        this.validFrom = validFrom;
        this.active = active;
    }

    public Long getId() {
        return id;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    // … getter + setter for every other field, in declaration order (boolean: isActive / setActive)
}
```

